"""Plot CSV evidence generated by the Julia case-study scripts.

Usage: python docs/benchmarks/plot_case_studies.py
Requires numpy and matplotlib, never used by the Julia runtime or docs build.
"""
from pathlib import Path
import csv
import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

ASSETS = Path(__file__).resolve().parents[1] / "src" / "assets"
plt.rcParams.update({"font.size": 10, "axes.spines.top": False, "axes.spines.right": False})

def field(path):
    data = np.genfromtxt(path, delimiter=",", names=True)
    x = np.unique(data["a1"]); y = np.unique(data["a2"])
    return x, y, data["density"].reshape(len(y), len(x))

def transport():
    folder = ASSETS / "inguva_case1"
    names = [("reference", "Analytical bin averages"), ("upwind", "Upwind + SSPRK3"),
             ("weno5", "WENO5 + SSPRK3"), ("compact_adi4", "Compact/ADI variant (periodic)"),
             ("exact_shift", "Integer shifts (open)")]
    fig, axes = plt.subplots(2, 3, figsize=(12, 7.5), layout="constrained")
    for ax, (name, title) in zip(axes.flat, names):
        x, y, z = field(folder / f"{name}_100.csv")
        im = ax.pcolormesh(x, y, z, cmap="viridis", vmin=0, vmax=50, shading="nearest")
        ax.set(xlabel="$a_1$", ylabel="$a_2$", title=title, aspect="equal", xlim=(0,2), ylim=(0,2))
        fig.colorbar(im, ax=ax, label="Number density")
    ax = axes.flat[-1]
    x, y, exact = field(folder / "reference_100.csv")
    for name, title in names:
        _, _, z = field(folder / f"{name}_100.csv")
        j = np.argmin(abs(y-1.4))
        ax.plot(x, z[j], label={"reference":"Analytical","upwind":"Upwind","weno5":"WENO5", "compact_adi4":"Compact/ADI", "exact_shift":"Exact shift"}[name])
    ax.set(xlabel="$a_1$", ylabel="Number density", title="Cut near $a_2=1.4$", xlim=(0.8,1.9))
    ax.legend(fontsize=7,loc="upper left")
    fig.suptitle("Inguva–Braatz case 1: Gaussian transport, t=1, 100 × 100 bins")
    fig.savefig(folder / "solutions.png", dpi=180); fig.savefig(folder / "solutions.svg"); plt.close(fig)
    # Signed color scale exposes errors/undershoots hidden by the common density scale.
    fig, axes = plt.subplots(1, 3, figsize=(12,3.7), layout="constrained")
    for ax, name in zip(axes, ("upwind", "weno5", "compact_adi4")):
        _, _, z = field(folder / f"{name}_100.csv"); error=z-exact
        bound=max(np.max(abs(error)),1e-15)
        im=ax.pcolormesh(x,y,error,cmap="RdBu_r",vmin=-bound,vmax=bound,shading="nearest")
        ax.set(xlabel="$a_1$",ylabel="$a_2$",title=name,aspect="equal")
        fig.colorbar(im,ax=ax,label="Numerical − analytical density")
    fig.savefig(folder / "errors.png",dpi=180);plt.close(fig)

def cooling():
    folder=ASSETS / "cooling_benchmark"
    data=np.genfromtxt(folder / "moments.csv", delimiter=",",names=True,dtype=None,encoding="utf-8")
    ref=np.genfromtxt(folder / "reference.csv",delimiter=",",names=True)
    fig,axes=plt.subplots(2,2,figsize=(10,7),layout="constrained")
    for method in np.unique(data["method"]):
        subset=data[data["method"]==method];bins=max(subset["bins"]);subset=subset[subset["bins"]==bins]
        axes[0,0].plot(subset["time"],subset["concentration"],label=f"{method}, {bins} bins")
        for k in (0,3):
            err=abs(subset[f"mu{k}"]-ref[f"mu{k}"])/np.maximum(abs(ref[f"mu{k}"]),1e-30)
            axes[0,1].semilogy(subset["time"],np.maximum(err,1e-16),label=f"{method}, moment {k}")
        axes[1,1].plot(subset["time"],subset["material_drift"],label=method)
    axes[0,0].plot(ref["time"],ref["concentration"],"k--",label="Independent moment ODE")
    for p in sorted(folder.glob("*_psd.csv")):
        d=np.genfromtxt(p,delimiter=",",names=True)
        axes[1,0].plot(d["length"],d["density"],label=p.stem.replace("_psd",""))
    axes[0,0].set(xlabel="Time [s]",ylabel="Concentration [g/g water]")
    axes[0,1].set(xlabel="Time [s]",ylabel="Relative moment error")
    axes[1,0].set(xlabel="Crystal length [µm]",ylabel="Number density",title="Final distribution")
    axes[1,1].set(xlabel="Time [s]",ylabel="Material balance drift [g/g water]")
    for ax in axes.flat:ax.legend(fontsize=7)
    fig.suptitle("Gunawan laws: demonstration seed and c(0), not a published-figure reproduction")
    fig.savefig(folder / "coupled_solution.png",dpi=180);fig.savefig(folder / "coupled_solution.svg");plt.close(fig)

def lnp():
    folder=ASSETS / "lnp_demo"
    history=np.genfromtxt(folder / "history.csv",delimiter=",",names=True)
    psd=np.genfromtxt(folder / "psd.csv",delimiter=",",names=True)
    fig,axes=plt.subplots(1,3,figsize=(12,3.8),layout="constrained")
    axes[0].plot(history["time"]*1000,history["free_lipid"])
    axes[0].set(xlabel="Time [ms]",ylabel="Free lipid [kg/m³]")
    axes[1].plot(history["time"]*1000,history["intensity_mean_m"]*1e9)
    axes[1].set(xlabel="Time [ms]",ylabel="Paper-defined mean diameter [nm]")
    times=np.unique(psd["time"])
    for t in times[[len(times)//4,len(times)//2,-1]]:
        d=psd[psd["time"]==t]
        axes[2].semilogx(d["diameter_m"]*1e9,d["intensity_density_per_m"]*1e-9,label=f"{1000*t:g} ms")
    axes[2].set(xlabel="Diameter [nm]",ylabel="Normalized intensity density [1/nm]",xlim=(1,30))
    axes[2].legend()
    fig.suptitle("Synthetic LNP inputs — NOT a reproduction of Shin et al. Figure 4")
    fig.savefig(folder / "demonstration.png",dpi=180);fig.savefig(folder / "demonstration.svg");plt.close(fig)

if __name__=="__main__":
    import sys
    selected=sys.argv[1:] or ["transport","cooling","lnp"]
    for name in selected:
        {"transport":transport,"cooling":cooling,"lnp":lnp}[name]()
